"""Turn results.json into a readable Markdown report."""


def _p(w):
    if not w or w.get("p") is None:
        return "–"
    return f"{100 * w['p']:.0f}% [{100 * w['lo']:.0f}–{100 * w['hi']:.0f}] (n={w['n']})"


def _auc(a):
    if not a or a.get("auc") is None:
        return "–"
    return f"{a['auc']:.3f} [{a['lo']:.3f}–{a['hi']:.3f}]"


def write_report(results, run_info, path):
    M = results["models"]
    names = list(M)
    L = ["# Results", "",
         "Generated by `python -m aaeid.run`. Brackets are 95% intervals "
         "(Wilson for proportions, bootstrap for AUC).", ""]

    a = results["data"]["annotations"]
    L += ["## Data after cleaning", "",
          f"- Tweets loaded: {a['rows_loaded']}; duplicates removed: {a['duplicate_tweets_removed']}; "
          f"tweet identical to its SAE translation, removed: {a['identical_aae_sae_pairs_removed']}; final: {a['final_tweets']}",
          f"- Native naturalness labels: {a['original_naturalness']}", ""]
    e = results["data"]["external"]
    L += [f"- External rows labeled AAE: {e['dialect_label_AAE']}; overlap with training removed: "
          f"{e['overlap_with_training_removed']}; human 'uncertain' dropped: {e['human_review_uncertain_dropped']}", "",
          "| source | human-accepted | model-labeled only |", "|---|---|---|"]
    for src, d in sorted(e["by_source_and_tier"].items()):
        L.append(f"| {src} | {d.get('human', 0)} | {d.get('model', 0)} |")
    L += ["", "Only the human-accepted rows are primary evidence. The model-labeled rows were "
          "labeled AAE by a codebook-prompted model and were never checked by a person.", ""]

    L += ["## 1. In-domain: Twitter AAE vs its LLM SAE translation", "",
          "| model | AUC vs SAE (5x5 CV, mean ± sd) | AUC vs casual SAE | balanced acc @0.5 | recall @95% spec. | SAE false-positive | casual-SAE false-positive |",
          "|---|---|---|---|---|---|---|"]
    for n in names:
        cv, o = M[n]["cv"], M[n]["oof"]
        L.append(f"| {n} | {cv['auc_aae_vs_sae']['mean']:.3f} ± {cv['auc_aae_vs_sae']['sd']:.3f} | "
                 f"{cv['auc_aae_vs_casual_sae']['mean']:.3f} ± {cv['auc_aae_vs_casual_sae']['sd']:.3f} | "
                 f"{cv['balanced_acc_at_0.5']['mean']:.3f} | {_p(o['in_domain_recall_natural_aae'])} | "
                 f"{_p(o['sae_false_positive_rate'])} | {_p(o['casual_sae_false_positive_rate'])} |")
    L += ["", "The negatives are LLM-written. “Casual SAE” is the same translation lowercased, "
          "without punctuation and with spellings like “u”, “im”, “ppl”. A model that learned dialect "
          "should barely notice; a model that learned “informal vs formal” will drop.", ""]

    g = results["data"]["grammar_coverage"]
    L += ["## Grammar-rule coverage (% of lines where each rule fires)", "",
          "| rule | " + " | ".join(g) + " |", "|---|" + "---|" * len(g)]
    for r in next(iter(g.values())):
        L.append(f"| {r} | " + " | ".join(f"{g[c][r]:.1f}" for c in g) + " |")
    L += ["", "The rules are high-precision and low-recall: most natural AAE tweets contain none of them. "
          "If model-labeled rows fire rules far more often than human-accepted rows, the model labeler "
          "selected for these features, and grammar-based results on those rows are circular.", ""]

    L += ["## 2. Does the score track native judgment?", "",
          "| model | natural vs rejected tweets (AUC) | real vs performed back-translation (AUC) |",
          "|---|---|---|"]
    for n in names:
        o = M[n]["oof"]
        L.append(f"| {n} | {_auc(o['auc_native_natural_vs_rejected'])} | "
                 f"{_auc(o['auc_real_vs_performed_backtranslation'])} |")
    L += ["", "0.5 = coin flip. Models trained with hard negatives saw these label types in "
          "training (other folds), so their numbers here are in-distribution.", ""]

    anns = list(next(iter(M.values()))["leave_one_annotator_out"])
    L += ["## 3. Leave one annotator out (AUC on the held-out annotator's tweets)", "",
          "| model | " + " | ".join(f"held out {x}" for x in anns) + " |",
          "|---|" + "---|" * len(anns)]
    for n in names:
        lo = M[n]["leave_one_annotator_out"]
        L.append(f"| {n} | " + " | ".join(_auc(lo[x]) for x in anns) + " |")
    L.append("")

    L += ["## 4. Cross-register recall (human-accepted AAE only)", "",
          "Same threshold as section 1. Each cell: share of real AAE lines the model calls AAE.", ""]
    srcs = sorted({s for n in names for s in M[n]["cross_register"].get("human", {})})
    L += ["| model | " + " | ".join(srcs) + " |", "|---|" + "---|" * len(srcs)]
    for n in names:
        h = M[n]["cross_register"].get("human", {})
        L.append(f"| {n} | " + " | ".join(_p(h.get(s)) for s in srcs) + " |")
    mw = {s: next(M[n]["cross_register"]["human"][s]["median_words"] for n in names) for s in srcs}
    L += ["", "Median words per line: " + ", ".join(f"{s} {w:.0f}" for s, w in mw.items()) + ". Twitter median is about 18.", ""]

    L += ["### Length control: in-domain tweets cut to k words", "",
          "If recall on short tweets falls as far as on TV/movie lines, length explains the drop, not register.", "",
          "| model | " + " | ".join(f"k={k}" for k in next(iter(M.values()))["oof"]["recall_natural_aae_truncated"]) + " | full |",
          "|---|" + "---|" * (len(next(iter(M.values()))["oof"]["recall_natural_aae_truncated"]) + 1)]
    for n in names:
        o = M[n]["oof"]
        L.append(f"| {n} | " + " | ".join(_p(w) for w in o["recall_natural_aae_truncated"].values())
                 + f" | {_p(o['in_domain_recall_natural_aae'])} |")
    L.append("")

    L += ["## 5. Secondary: model-labeled rows (not human-checked)", ""]
    srcs2 = sorted({s for n in names for s in M[n]["cross_register"].get("model", {})})
    L += ["| model | " + " | ".join(srcs2) + " |", "|---|" + "---|" * len(srcs2)]
    for n in names:
        h = M[n]["cross_register"].get("model", {})
        L.append(f"| {n} | " + " | ".join(_p(h.get(s)) for s in srcs2) + " |")
    L.append("")

    L += ["## 6. What the strongest model leans on", ""]
    for n in names:
        f = M[n]["features"]
        if f["grammar_rules"]:
            L.append(f"- **{n}** grammar-rule weights: " + ", ".join(f"{k.split(':')[-1]} {v}" for k, v in f["grammar_rules"]))
        L.append(f"- **{n}** top AAE features: " + ", ".join(k.split("__")[-1] for k, _ in f["most_aae"][:15]))
    L += ["", "## Run info", "",
          f"- config sha256 `{run_info['config_sha256'][:12]}`, python {run_info['python']}, "
          f"scikit-learn {run_info['scikit_learn']}, numpy {run_info['numpy']}, pandas {run_info['pandas']}",
          "- input files and hashes: see `run_info.json`", ""]
    path.write_text("\n".join(L))
